    """Parse a JSON number literal into (neg, digits, exponent)."""
    neg = lit[0] == '-'
    body = lit[1:] if neg else lit
    mant = body
    epart = None
    for i, c in enumerate(body):
        if c == 'e' or c == 'E':
            mant = body[:i]
            epart = body[i+1:]
            break
    if '.' in mant:
        ip, fp = mant.split('.', 1)
    else:
        ip, fp = mant, ''
    exp = -len(fp)
    if epart is not None:
        try:
            exp += int(epart)
        except ValueError:
            exp += 0
    digits = ip + fp
    i = 0
    n = len(digits)
    while i < n and digits[i] == '0':
        i += 1
    if i == n:
        digits = '0'
    else:
        digits = digits[i:]
    return neg, digits, exp

