# ---------------------------------------------------------------------------
# Value helpers
# ---------------------------------------------------------------------------

def jq_type(v):
    if v is None:
        return 'null'
    if v is True or v is False:
        return 'boolean'
    if isinstance(v, float):
        return 'number'
    if isinstance(v, str):
        return 'string'
    if isinstance(v, list):
        return 'array'
    if isinstance(v, dict):
        return 'object'
    raise Exception('bad value %r' % (v,))

KIND_RANK = {'null': 0, 'boolean': 1, 'number': 3, 'string': 4, 'array': 5, 'object': 6}

def jq_kind_name(k):
    return k

def is_true(v):
    return v is not None and v is not False

def jq_equal(a, b):
    ta = jq_type(a)
    tb = jq_type(b)
    if ta != tb:
        return False
    if ta == 'null':
        return True
    if ta == 'boolean':
        return a == b
    if ta == 'number':
        return num_equal(a, b)
    if ta == 'string':
        return a == b
    if ta == 'array':
        if len(a) != len(b):
            return False
        for x, y in zip(a, b):
            if not jq_equal(x, y):
                return False
        return True
    # object
    if len(a) != len(b):
        return False
    for k in a:
        if k not in b:
            return False
        if not jq_equal(a[k], b[k]):
            return False
    return True

