    ta = jq_type(a)
    tb = jq_type(b)
    if ta != tb:
        ra = KIND_RANK[ta]
        rb = KIND_RANK[tb]
        if ra < rb:
            return -1
        return 1
    if ta == 'null':
        return 0
    if ta == 'boolean':
        if a == b:
            return 0
        return -1 if a is False else 1
    if ta == 'number':
        return num_cmp(a, b)
    if ta == 'string':
        if a == b:
            return 0
        return -1 if a < b else 1
    if ta == 'array':
        n = min(len(a), len(b))
        for i in range(n):
            r = jq_cmp(a[i], b[i])
            if r != 0:
