import codecs as _codecs
import re as _re

_NONASCII = _re.compile(rb'[\x80-\xff]+')

def utf8_chars(data):
    """Return (chars, byte-lengths) for a bytes object."""
    chars = []
    blen = bytearray()
    pos = 0
    for m in _NONASCII.finditer(data):
        a, b = m.span()
        if a > pos:
            seg = data[pos:a]
            chars.append(seg.decode('latin-1'))
            blen.extend(b'\x01' * (a - pos))
        dec = _codecs.getincrementaldecoder('utf-8')(errors='replace')
        k = 0
        for i in range(a, b):
            k += 1
            s = dec.decode(data[i:i+1])
            if s:
                for c in s:
                    chars.append(c)
                    blen.append(k)
                k = 0
        s = dec.decode(b'', True)
        if s:
            for c in s:
                chars.append(c)
                blen.append(k)
        pos = b
    if pos < len(data):
        seg = data[pos:]
        chars.append(seg.decode('latin-1'))
        blen.extend(b'\x01' * (len(data) - pos))
    return ''.join(chars), blen

_WHITESPACE = ' \t\n\r\x0c'
_DELIMS = '{}[],:'

_NUM_RE = _re.compile(r'^[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?$')

HEXDIG = '0123456789abcdefABCDEF'

class _Frame:
    __slots__ = ('kind', 'val', 'key', 'expect', 'after_comma')
    def __init__(self, kind):
        self.kind = kind
        self.val = [] if kind == 'a' else {}
        self.key = None
        self.expect = True
        self.after_comma = False

class JvParser:
    def __init__(self, seq=False):
        self.line = 1
        self.col = 0
        self.st = 0            # 0 normal, 1 string, 2 escape, 3 uni
        self.token = []
        self.frames = []
        self.strbuf = []
        self.unic = 0
        self.unival = 0
        self.hi_pending = False
        self.strerr = None     # (msg, line, col) deferred
        self.seq = seq
        self.out = []

    # -- helpers ----------------------------------------------------------
    def _err(self, msg, eof=False):
        raise ParseError(msg, self.line, self.col, eof)

    def process_value(self, v):
        if self.frames:
            fr = self.frames[-1]
            if not fr.expect:
                self._err('Expected separator between values')
            if fr.kind == 'a':
                fr.val.append(v)
            else:
                if fr.key is None:
                    if jq_type(v) != 'string':
                        self._err('Object keys must be strings')
                    fr.key = v
                else:
                    fr.val[fr.key] = v
                    fr.key = None
            fr.expect = False
            fr.after_comma = False
        else:
            self.out.append(v)

    def close_top(self):
        fr = self.frames.pop()
        self.process_value(fr.val)

    def handle_delim(self, ch):
        if not self.frames:
            if ch == '{' or ch == '[':
                self.frames.append(_Frame('o' if ch == '{' else 'a'))
                return
            if ch == ',':
                self._err("Expected value before ','")
            if ch == ']':
                self._err("Unmatched ']'")
            if ch == '}':
                self._err("Unmatched '}'")
            self._err("Expected value before ','")
        fr = self.frames[-1]
        if fr.kind == 'a':
            if ch == ',':
                if fr.expect:
                    self._err("Expected value before ','")
                fr.expect = True
                fr.after_comma = True
            elif ch == ']':
                if fr.expect:
                    if fr.after_comma:
                        self._err('Expected another array element')
                self.close_top()
            elif ch == '{':
                if not fr.expect:
                    self._err('Expected separator between values')
                self.frames.append(_Frame('o'))
            elif ch == '[':
                if not fr.expect:
                    self._err('Expected separator between values')
                self.frames.append(_Frame('a'))
            elif ch == ':':
                self._err("Expected value before ','")
            else:
                self._err('Expected separator between values')
        else:
            if ch == ':':
                if fr.key is None:
                    self._err('Object keys must be strings')
                fr.expect = True
            elif ch == ',':
                if fr.expect:
                    self._err("Expected value before ','")
                if fr.key is not None:
                    self._err('Objects must consist of key:value pairs')
                fr.expect = True
                fr.after_comma = True
            elif ch == '}':
                if fr.key is not None:
                    self._err('Objects must consist of key:value pairs')
                if fr.expect:
                    if fr.after_comma:
                        self._err('Expected another key-value pair')
                self.close_top()
            elif ch == '[':
                if not fr.expect:
                    self._err('Expected separator between values')
                self.frames.append(_Frame('a'))
            elif ch == '{':
                if not fr.expect:
                    self._err('Expected separator between values')
                self.frames.append(_Frame('o'))
            else:
                self._err('Expected separator between values')

    def flush_token(self, eof=False):
        if not self.token:
            return
        tok = ''.join(self.token)
        self.token = []
        v = self.parse_literal(tok, eof)
        self.process_value(v)

    def parse_literal(self, tok, eof=False):
        if tok == 'true':
            return True
        if tok == 'false':
            return False
        if tok == 'null':
            return None
        low = tok.lower()
        if low == 'nan':
            return float('nan')
        if low == 'inf' or low == 'infinity':
            return float('inf')
        if low == '-inf' or low == '-infinity':
            return float('-inf')
        if _NUM_RE.match(tok):
            return parse_number_literal(tok)
        if eof:
            if tok[0] == 't' or tok[0] == 'f' or (tok[0] == 'n' and len(tok) > 1 and tok[1] == 'u'):
                self._err('Invalid literal', True)
            self._err('Invalid numeric literal', True)
        else:
            if tok[0] == 't' or tok[0] == 'f' or (tok[0] == 'n' and len(tok) > 1 and tok[1] == 'u'):
                self._err('Invalid literal')
            self._err('Invalid numeric literal')

    def string_error(self):
        e = self.strerr
        if e is not None:
            self.line, self.col = e[1], e[2]
            self._err(e[0])

    def finish_string(self):
        st = self.st
        self.st = 0
        if st != 0:
            if st == 1 and not self.unic and self.hi_pending:
                pass
        # deferred errors have the highest precedence
        self.string_error()
        if self.hi_pending:
            self._err('Invalid \\uXXXX\\uXXXX surrogate pair escape')
        if self.unic:
            self._err('Invalid \\uXXXX escape')
        s = ''.join(self.strbuf)
        self.strbuf = []
        self.hi_pending = False
        self.process_value(s)

    def add_uni(self):
        cp = self.unival
        self.unic = 0
        self.unival = 0
        if self.hi_pending:
            if 0xdc00 <= cp <= 0xdfff:
                self.hi_pending = False
                self.strbuf.append(chr(self.hi_val + ((cp - 0xdc00) << 0) + 0x10000 - 0x10000))
            else:
                self.strerr = ('Invalid \\uXXXX\\uXXXX surrogate pair escape', self.line, self.col)
                self.st = 1
                return
            self.st = 1
            return
        if 0xd800 <= cp <= 0xdbff:
            self.hi_pending = True
            self.hi_val = (cp - 0xd800) << 10
            self.st = 1
            return
        if 0xdc00 <= cp <= 0xdfff:
            cp = 0xfffd
        self.strbuf.append(chr(cp))
        self.st = 1

    def process(self, ch):
        st = self.st
        if st == 1:
            if ch == '\\':
                self.st = 2
                return
            if ch == '"':
                self.finish_string()
                return
            o = ord(ch)
            if o < 0x20:
                self.strerr = ('Invalid string: control characters from U+0000 through U+001F must be escaped',
                               self.line, self.col)
                self.strbuf.append(ch)
                return
            if self.hi_pending:
                self.strerr = ('Invalid \\uXXXX\\uXXXX surrogate pair escape', self.line, self.col)
            self.strbuf.append(ch)
            return
        if st == 2:
            if ch == 'u':
                self.st = 3
                self.unic = 0
                self.unival = 0
                self.uni_low = self.hi_pending
                return
            m = {'"': '"', '\\': '\\', '/': '/', 'b': '\x08', 'f': '\x0c',
                 'n': '\x0a', 'r': '\x0d', 't': '\x09'}
            self.st = 1
            if ch in m:
                if self.hi_pending:
                    self.strerr = ('Invalid \\uXXXX\\uXXXX surrogate pair escape', self.line, self.col)
                self.strbuf.append(m[ch])
            else:
                self.strerr = ('Invalid escape', self.line, self.col)
            return
        if st == 3:
            if ch in HEXDIG:
                self.unival = self.unival * 16 + int(ch, 16)
                self.unic += 1
                if self.unic == 4:
                    self.add_uni()
                return
            self.strerr = ('Invalid characters in \\uXXXX escape', self.line, self.col)
            self.st = 1
            return
        # normal
        if ch in _WHITESPACE:
            self.flush_token()
            return
        if ch in _DELIMS:
            self.flush_token()
            self.handle_delim(ch)
            return
        self.token.append(ch)

    def finish(self):
        if self.st != 0:
            raise ParseError('Unfinished string at EOF', self.line, self.col, True)
        self.flush_token(True)
        if self.frames:
            raise ParseError('Unfinished JSON term at EOF', self.line, self.col, True)

def parse_number_literal(tok):
    v = float(tok)
    try:
        return Num(v, tok)
    except (OverflowError, ValueError):
        return v

def json_values(data, seq=False):
    """Yield JSON values from data (bytes)."""
    chars, blen = utf8_chars(data)
    p = JvParser(seq)
    i = 0
    n = len(chars)
    for i in range(n):
        ch = chars[i]
        p.col += blen[i]
        if ch == '\n':
            p.line += 1
            p.col = 0
        p.process(ch)
        if p.out:
            for v in p.out:
                yield v
            p.out = []
    p.finish()
    for v in p.out:
        yield v

def parse_json_one(data, what='input'):
    vals = list(json_values(data))
    return vals
