# ---------------------------------------------------------------------------
# jq language lexer
# ---------------------------------------------------------------------------
KEYWORDS = {'def', 'as', 'if', 'then', 'elif', 'else', 'end', 'reduce',
            'foreach', 'try', 'catch', 'label', 'import', 'include',
            'and', 'or'}

IDSTART = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_')
IDCHARS = IDSTART | set('0123456789')

MULTI_OPS = ['?//', '|=', '+=', '-=', '*=', '/=', '%=', '//=', '==', '!=',
             '<=', '>=', '//']
SINGLE_OPS = set('|,;:()[]{}?=+-*/%<>')

def op_display(op):
    if len(op) == 1:
        return "'" + op + "'"
    return op

class Tok:
    __slots__ = ('kind', 'val', 'line', 'col', 'n')
    def __init__(self, kind, val, line, col, n):
        self.kind = kind
        self.val = val
        self.line = line
        self.col = col
        self.n = n
    def display(self):
        k = self.kind
        if k == 'IDENT':
            return 'IDENT'
        if k == 'LITERAL':
            return 'LITERAL'
        if k == 'BINDING':
            return 'BINDING'
        if k == 'FORMAT':
            return 'FORMAT'
        if k == 'FIELD':
            return 'FIELD'
        if k == 'DOT':
            return "'.'"
        if k == 'REC':
            return "'..'"
        if k == 'OP':
            return op_display(self.val)
        if k == 'KW':
            return self.val
        if k == 'STR':
            return 'QQSTRING_START'
        if k == 'STRT':
            return 'QQSTRING_TEXT'
        if k == 'STRI':
            return 'QQSTRING_INTERP_START'
        if k == 'STRE':
            return 'QQSTRING_INTERP_END'
        if k == 'STREND':
            return 'QQSTRING_END'
        if k == 'INVALID':
            return 'INVALID_CHARACTER'
        return k

def lex(src):
    """Tokenize a jq program.  Yields Tok objects. Raises CompileError-like
    syntax error info through the parser."""
    toks = []
    i = 0
    n = len(src)
    line = 1
    col = 0
    while i < n:
        c = src[i]
        if c == '\n':
            line += 1
            col = 0
            i += 1
            continue
        if c in ' \t\r\f':
            col += 1
            i += 1
            continue
        if c == '#':
            while i < n and src[i] != '\n':
                i += 1
                col += 1
            continue
        start_col = col + 1
        # identifier / keyword
