        t = tok if tok is not None else self.peek()
        raise JqSyntax(msg or ('syntax error, unexpected %s' % t.display()), t)

    def expect_op(self, op):
        t = self.peek()
        if t.kind == 'OP' and t.val == op:
            self.p += 1
            return t
