    def expect_kw(self, kw):
        t = self.peek()
        if t.kind == 'KW' and t.val == kw:
            self.p += 1
            return t
        self.error("syntax error, unexpected %s, expecting %s" % (t.display(), kw))

    def expect_kind(self, kind):
        t = self.peek()
        if t.kind == kind:
            self.p += 1
            return t
