            pass
        nt = self.peek()
        if nt.kind == 'OP' and nt.val == '(':
            self.next()
            while True:
                pt = self.peek()
                if pt.kind == 'IDENT':
                    self.next()
                    params.append(('v', pt.val))
                elif pt.kind == 'BINDING':
                    self.next()
                    params.append(('b', pt.val))
