    def parse_pattern(self):
        t = self.peek()
        if t.kind == 'BINDING':
            self.next()
            return ('pb', t.val)
        if t.kind == 'OP' and t.val == '[':
            self.next()
            elems = []
            if self.peek().kind == 'OP' and self.peek().val == ']':
                self.next()
                return ('parr', elems)
            while True:
                elems.append(self.parse_pattern())
                nt = self.peek()
                if nt.kind == 'OP' and nt.val == ',':
                    self.next()
                    continue
                break
            self.expect_op(']')
            return ('parr', elems)
