            self.expect_op(':')
            return (('s', key), self.parse_pattern())
        if t.kind == 'OP' and t.val == '(':
            self.next()
            e = self.parse_pipe()
            self.expect_op(')')
            self.expect_op(':')
            return (('e', e), self.parse_pattern())
