                   % t.display())

    def parse_alt(self):
        left = self.parse_assign()
        t = self.peek()
        if t.kind == 'OP' and t.val == '//':
            self.next()
            right = self.parse_alt()
            return ('alt', left, right)
        return left

    def parse_assign(self):
        left = self.parse_or()
        t = self.peek()
        if t.kind == 'OP' and t.val in ASSIGN_OPS:
            self.next()
            right = self.parse_alt()
            if t.val == '=':
                return ('assign', left, right)
            return ('update', left, right, t.val)
        return left

    def parse_or(self):
        left = self.parse_and()
        while True:
            t = self.peek()
            if t.kind == 'KW' and t.val == 'or':
                self.next()
                right = self.parse_and()
                left = ('or', left, right)
            else:
                return left

    def parse_and(self):
        left = self.parse_cmp()
        while True:
            t = self.peek()
            if t.kind == 'KW' and t.val == 'and':
                self.next()
                right = self.parse_cmp()
                left = ('and', left, right)
            else:
                return left

    def parse_cmp(self):
        left = self.parse_add()
        t = self.peek()
        if t.kind == 'OP' and t.val in CMP_OPS:
            self.next()
            right = self.parse_add()
            return ('binop', t.val, left, right)
        return left

    def parse_add(self):
