        while True:
            t = self.peek()
            if t.kind == 'OP' and (t.val == '+' or t.val == '-'):
                self.next()
                right = self.parse_mul()
                left = ('binop', t.val, left, right)
            else:
                return left

    def parse_mul(self):
        left = self.parse_unary()
        while True:
            t = self.peek()
            if t.kind == 'OP' and t.val in ('*', '/', '%'):
                self.next()
                right = self.parse_unary()
                left = ('binop', t.val, left, right)
            else:
                return left

