        elif t.kind == 'REC':
            self.next()
            e = ('recurse',)
        elif t.kind == 'FIELD':
            self.next()
            e = ('field', t.val)
        elif t.kind == 'LITERAL':
            self.next()
            e = ('const', t.val)
        elif t.kind == 'STR':
            e = self.parse_string_value()
        elif t.kind == 'FORMAT':
