            self.next()
            e = self.parse_pipe()
            self.expect_op(')')
        elif t.kind == 'OP' and t.val == '[':
            self.next()
            if self.peek().kind == 'OP' and self.peek().val == ']':
                self.next()
                e = ('array', None)
            else:
                inner = self.parse_pipe()
                self.expect_op(']')
                e = ('array', inner)
        elif t.kind == 'OP' and t.val == '{':
            e = self.parse_object()
        elif t.kind == 'BINDING':
            self.next()
            if t.val == '__loc__':
                e = ('loc',)
            else:
                e = ('var', t.val)
