            body = self.parse_term()
            catch = None
            nt = self.peek()
            if nt.kind == 'KW' and nt.val == 'catch':
                self.next()
                catch = self.parse_term()
            e = ('try', body, catch)
        elif t.kind == 'KW' and t.val == 'reduce':
