                self.next()
                return parts
            elif t.kind == 'EOF':
                self.error("syntax error, unexpected end of file, expecting QQSTRING_TEXT or "
                           "QQSTRING_INTERP_START or QQSTRING_END", self.toks[self.p-1])
            else:
                self.error("syntax error, unexpected %s, expecting QQSTRING_TEXT or "
                           "QQSTRING_INTERP_START or QQSTRING_END" % t.display())

    def parse_string_value(self):
        parts = self.parse_string_parts()
        return ('str', parts, None)

    def parse_string_field(self):
        parts = self.parse_string_parts()
        return ('indexstr', ('str', parts, None))
