            pass
        if lo < 0:
            lo += n
        if hi < 0:
            hi += n
        if lo < 0:
            lo = 0
        if hi > n:
            hi = n
        if lo > hi:
            lo = hi
        return v[lo:hi]
    raise JQError('Cannot index %s with object' % jq_type(v))

def truthy(v):
    return v is not None and v is not False

def arith_error(a, b, op):
    na = {'+': 'added', '-': 'subtracted', '*': 'multiplied', '/': 'divided',
          '%': 'divided (remainder)'}
    return JQError('%s (%s) and %s (%s) cannot be %s' % (
        jq_type(a), jv_dump_str(a, COMPACT_OPTS) if jq_type(a) in ('string', 'object') else
        (jv_dump_str(a, COMPACT_OPTS) if jq_type(a) == 'number' else jv_dump_str(a, COMPACT_OPTS)),
        jq_type(b), jv_dump_str(b, COMPACT_OPTS), na[op]))

def dumpval(v):
    t = jq_type(v)
    if t in ('number', 'string', 'object'):
        return jv_dump_str(v, COMPACT_OPTS)
    return jv_dump_str(v, COMPACT_OPTS)

