    if op == '+':
        return add_values(a, b)
    if op == '-':
        return sub_values(a, b)
    if op == '*':
        return mul_values(a, b)
    if op == '/':
        return div_values(a, b)
    if op == '%':
        return mod_values(a, b)
    if op == '==':
        return jq_equal(a, b)
    if op == '!=':
        return not jq_equal(a, b)
    if op == '<':
        return jq_cmp(a, b) < 0
    if op == '>':
        return jq_cmp(a, b) > 0
    if op == '<=':
        return jq_cmp(a, b) <= 0
    if op == '>=':
        return jq_cmp(a, b) >= 0
    raise JQError('internal error: bad op %s' % op)

def ev_object(pairs, inp, env, st, i, acc):
    if i >= len(pairs):
        yield dict(acc)
        return
    kexpr, vexpr = pairs[i]
    for k in ev(kexpr, inp, env, st):
        if jq_type(k) != 'string':
            raise JQError('Object keys must be strings')
        if vexpr is None:
            acc2 = dict(acc)
            acc2[k] = None
            yield from ev_object(pairs, inp, env, st, i + 1, acc2)
        else:
            for v in ev(vexpr, inp, env, st):
                acc2 = dict(acc)
                acc2[k] = v
                yield from ev_object(pairs, inp, env, st, i + 1, acc2)

def ev_string(node, inp, env, st):
    parts = node[1]
    fmt = node[2]
    yield from ev_string1(parts, inp, env, st, fmt, 0, [])

def ev_string1(parts, inp, env, st, fmt, i, acc):
    if i >= len(parts):
        yield ''.join(acc)
        return
    p = parts[i]
    if p[0] == 'text':
        acc.append(p[1])
        yield from ev_string1(parts, inp, env, st, fmt, i + 1, acc)
        acc.pop()
    else:
        for v in ev(p[1], inp, env, st):
            if fmt is None:
                s = jv_tostring(v)
            else:
                s = apply_format(fmt, v, st)
            acc.append(s)
            yield from ev_string1(parts, inp, env, st, fmt, i + 1, acc)
            acc.pop()

def bind_patterns(pats, v, env, st):
    """Yield (env, list-of-bindings) for each pattern alternative."""
    yield from bind_pat_alt(pats, v, env, st, 0)

def bind_pat_alt(pats, v, env, st, i):
    if i >= len(pats):
        return
    try:
        for subenv in bind_pat(pats[i], v, env, st):
            yield subenv
    except JQError:
        yield from bind_pat_alt(pats, v, env, st, i + 1)

def bind_pat(pat, v, env, st):
    t = pat[0]
    if t == 'pb':
        e = Env(env)
        e.vars[pat[1]] = v
        yield e
    elif t == 'parr':
        elems = pat[1]
        yield from bind_pat_arr(elems, v, env, st, 0, {})
    elif t == 'pobj':
        elems = pat[1]
        yield from bind_pat_obj(elems, v, env, st, 0, {})
    else:
        raise JQError('Invalid pattern')

def bind_pat_arr(elems, v, env, st, i, binds):
    if i >= len(elems):
        e = Env(env)
        e.vars.update(binds)
        yield e
        return
    val = index_num(v, float(i)) if isinstance(v, list) or v is None else (_for_err(v))
