# ---------------------------------------------------------------------------
# Main evaluator
# ---------------------------------------------------------------------------

def ev(node, inp, env, st):
    t = node[0]
    if t == 'const':
        yield node[1]
    elif t == 'identity':
        yield inp
    elif t == 'pipe':
        for a in ev(node[1], inp, env, st):
            yield from ev(node[2], a, env, st)
    elif t == 'comma':
        yield from ev(node[1], inp, env, st)
        yield from ev(node[2], inp, env, st)
    elif t == 'field':
        name = node[1]
        ty = jq_type(inp)
        if ty == 'object':
            yield inp.get(name)
        elif ty == 'null':
            yield None
        else:
            raise JQError('Cannot index %s with string "%s"' % (ty, name))
    elif t == 'index':
        for k in ev(node[1], inp, env, st):
            yield index_value(inp, k)
    elif t == 'indexstr':
        for s in ev(node[1], inp, env, st):
            yield index_value(inp, s)
    elif t == 'slice':
        frm = node[1]
        to = node[2]
        if frm is None:
            for b in ev(to, inp, env, st):
                yield slice_value(inp, None, b)
        elif to is None:
            for a in ev(frm, inp, env, st):
                yield slice_value(inp, a, None)
        else:
            for a in ev(frm, inp, env, st):
                for b in ev(to, inp, env, st):
                    yield slice_value(inp, a, b)
    elif t == 'iterate':
        ty = jq_type(inp)
        if ty == 'array':
            for x in inp:
                yield x
        elif ty == 'object':
            for x in inp.values():
                yield x
        else:
            raise JQError('Cannot iterate over %s (%s)' % (ty, dumpval(inp)))
    elif t == 'optional':
        try:
            yield from ev(node[1], inp, env, st)
        except JQError:
            pass
    elif t == 'recurse':
        yield from recurse_gen(inp, env, st)
    elif t == 'neg':
        for a in ev(node[1], inp, env, st):
            yield negate_value(a)
    elif t == 'binop':
        op = node[1]
        for a in ev(node[2], inp, env, st):
            for b in ev(node[3], inp, env, st):
                yield binop_value(op, a, b)
    elif t == 'and':
        for a in ev(node[1], inp, env, st):
            if not truthy(a):
                yield False
            else:
                for b in ev(node[2], inp, env, st):
                    yield truthy(b)
    elif t == 'or':
        for a in ev(node[1], inp, env, st):
            if truthy(a):
                yield True
            else:
                for b in ev(node[2], inp, env, st):
                    yield truthy(b)
    elif t == 'alt':
        found = False
        try:
            for a in ev(node[1], inp, env, st):
                if truthy(a):
                    found = True
                    yield a
        except JQError:
            pass
        if not found:
            yield from ev(node[2], inp, env, st)
    elif t == 'try':
        try:
            yield from ev(node[1], inp, env, st)
        except JQError as e:
            if node[2] is None:
                pass
            else:
                yield from ev(node[2], e.value, env, st)
    elif t == 'if':
        yield from ev_if(node, inp, env, st)
    elif t == 'reduce':
        yield from ev_reduce(node, inp, env, st)
    elif t == 'foreach':
        yield from ev_foreach(node, inp, env, st)
    elif t == 'as':
        for v in ev(node[1], inp, env, st):
            for subenv, _ in bind_patterns(node[2], v, env, st):
                yield from ev(node[3], inp, subenv, st)
    elif t == 'funcdef':
