        yield from ev(node[4], inp, newenv, st)
    elif t == 'label':
        lab = ('label', node[1])
        env2 = Env(env)
        env2.vars[node[1]] = lab
        try:
            yield from ev(node[2], inp, env2, st)
        except Break as b:
            if b.name != node[1]:
                raise
    elif t == 'break':
        raise Break(node[1])
    elif t == 'var':
        v = env.get_var(node[1])
        if v is _UNDEF:
            raise CompileError('$%s is not defined' % node[1])
        yield v
    elif t == 'loc':
        yield {'file': st.prog_filename, 'line': st.prog_line}
    elif t == 'call':
        yield from ev_call(node, inp, env, st)
    elif t == 'array':
        if node[1] is None:
            yield []
        else:
            yield list(ev(node[1], inp, env, st))
    elif t == 'object':
        yield from ev_object(node[1], inp, env, st, 0, {})
    elif t == 'str':
        yield from ev_string(node, inp, env, st)
    elif t == 'format':
        yield apply_format(node[1], inp, st)
    elif t == 'assign':
        yield from ev_assign(node, inp, env, st)
    elif t == 'update':
        yield from ev_update(node, inp, env, st)
    else:
        raise JQError('internal error: unknown node %r' % (t,))

