    if op == '+':
        return add_values(a, b)
    if op == '-':
        return sub_values(a, b)
    if op == '*':
        return mul_values(a, b)
    if op == '/':
        return div_values(a, b)
    if op == '%':
        return mod_values(a, b)
    if op == '==':
        return jq_equal(a, b)
    if op == '!=':
        return not jq_equal(a, b)
    if op == '<':
        return jq_cmp(a, b) < 0
    if op == '>':
        return jq_cmp(a, b) > 0
    if op == '<=':
        return jq_cmp(a, b) <= 0
    if op == '>=':
        return jq_cmp(a, b) >= 0
