            acc2 = dict(acc)
            acc2[k] = None
            yield from ev_object(pairs, inp, env, st, i + 1, acc2)
        else:
            for v in ev(vexpr, inp, env, st):
                acc2 = dict(acc)
                acc2[k] = v
                yield from ev_object(pairs, inp, env, st, i + 1, acc2)

