            val = None
        elif isinstance(v, dict):
            if name not in v:
                raise JQError('Cannot index object with "%s"' % name)
            val = v[name]
        else:
            raise JQError('Cannot index %s with "%s"' % (jq_type(v), name))
        nb = dict(binds)
        nb[name] = val
        yield from bind_pat_obj(elems, v, env, st, i + 1, nb)
    else:
        for k in ev(keyspec[1], v, env, st):
