                for b in ev(to, inp, env, st):
                    yield slice_value(inp, a, b)
    elif t == 'iterate':
        ty = jq_type(inp)
        if ty == 'array':
            for x in inp:
                yield x
        elif ty == 'object':
            for x in inp.values():
                yield x
        else:
            raise JQError('Cannot iterate over %s (%s)' % (ty, dumpval(inp)))
    elif t == 'optional':
        try:
            yield from ev(node[1], inp, env, st)
        except JQError:
            pass
    elif t == 'recurse':
        yield from recurse_gen(inp, env, st)
    elif t == 'neg':
        for a in ev(node[1], inp, env, st):
            yield negate_value(a)
    elif t == 'binop':
        op = node[1]
        for a in ev(node[2], inp, env, st):
            for b in ev(node[3], inp, env, st):
                yield binop_value(op, a, b)
    elif t == 'and':
        for a in ev(node[1], inp, env, st):
            if not truthy(a):
                yield False
            else:
                for b in ev(node[2], inp, env, st):
                    yield truthy(b)
    elif t == 'or':
        for a in ev(node[1], inp, env, st):
            if truthy(a):
                yield True
            else:
                for b in ev(node[2], inp, env, st):
                    yield truthy(b)
    elif t == 'alt':
        found = False
        try:
            for a in ev(node[1], inp, env, st):
                if truthy(a):
                    found = True
                    yield a
        except JQError:
            pass
        if not found:
            yield from ev(node[2], inp, env, st)
    elif t == 'try':
        try:
            yield from ev(node[1], inp, env, st)
        except JQError as e:
            if node[2] is None:
                pass
            else:
                yield from ev(node[2], e.value, env, st)
    elif t == 'if':
        yield from ev_if(node, inp, env, st)
    elif t == 'reduce':
        yield from ev_reduce(node, inp, env, st)
    elif t == 'foreach':
        yield from ev_foreach(node, inp, env, st)
    elif t == 'as':
        for v in ev(node[1], inp, env, st):
            for subenv, _ in bind_patterns(node[2], v, env, st):
                yield from ev(node[3], inp, subenv, st)
    elif t == 'funcdef':
        newenv = Env(env)
        newenv.funcs[(node[1], len(node[2]))] = (node[2], node[3], newenv)
        yield from ev(node[4], inp, newenv, st)
    elif t == 'label':
        lab = ('label', node[1])
        env2 = Env(env)
        env2.vars[node[1]] = lab
        try:
            yield from ev(node[2], inp, env2, st)
        except Break as b:
            if b.name != node[1]:
                raise
    elif t == 'break':
        raise Break(node[1])
    elif t == 'var':
        v = env.get_var(node[1])
        if v is _UNDEF:
            raise CompileError('$%s is not defined' % node[1])
        yield v
    elif t == 'loc':
        yield {'file': st.prog_filename, 'line': st.prog_line}
    elif t == 'call':
        yield from ev_call(node, inp, env, st)
    elif t == 'array':
        if node[1] is None:
            yield []
        else:
            yield list(ev(node[1], inp, env, st))
    elif t == 'object':
        yield from ev_object(node[1], inp, env, st, 0, {})
    elif t == 'str':
        yield from ev_string(node, inp, env, st)
    elif t == 'format':
        yield apply_format(node[1], inp, st)
    elif t == 'assign':
        yield from ev_assign(node, inp, env, st)
    elif t == 'update':
        yield from ev_update(node, inp, env, st)
    else:
        raise JQError('internal error: unknown node %r' % (t,))

def recurse_gen(v, env, st):
    yield v
    ty = jq_type(v)
    if ty == 'array':
        for x in v:
            yield from recurse_gen(x, env, st)
    elif ty == 'object':
        for x in v.values():
            yield from recurse_gen(x, env, st)

def ev_if(node, inp, env, st):
    branches = node[1]
    els = node[2]
    yield from ev_if1(branches, els, inp, env, st, 0)

def ev_if1(branches, els, inp, env, st, i):
    if i >= len(branches):
        if els is None:
            yield inp
        else:
            yield from ev(els, inp, env, st)
        return
    cond, then = branches[i]
    for c in ev(cond, inp, env, st):
        if truthy(c):
            yield from ev(then, inp, env, st)
        else:
            yield from ev_if1(branches, els, inp, env, st, i + 1)

def binop_value(op, a, b):
    if op == '+':
        return add_values(a, b)
    if op == '-':
        return sub_values(a, b)
    if op == '*':
        return mul_values(a, b)
    if op == '/':
        return div_values(a, b)
    if op == '%':
        return mod_values(a, b)
    if op == '==':
        return jq_equal(a, b)
    if op == '!=':
        return not jq_equal(a, b)
    if op == '<':
        return jq_cmp(a, b) < 0
    if op == '>':
        return jq_cmp(a, b) > 0
    if op == '<=':
        return jq_cmp(a, b) <= 0
    if op == '>=':
        return jq_cmp(a, b) >= 0
