    """Yield (env, list-of-bindings) for each pattern alternative."""
    yield from bind_pat_alt(pats, v, env, st, 0)

def bind_pat_alt(pats, v, env, st, i):
    if i >= len(pats):
        return
    try:
        for subenv in bind_pat(pats[i], v, env, st):
            yield subenv
    except JQError:
        yield from bind_pat_alt(pats, v, env, st, i + 1)

def bind_pat(pat, v, env, st):
    t = pat[0]
    if t == 'pb':
        e = Env(env)
        e.vars[pat[1]] = v
        yield e
    elif t == 'parr':
        elems = pat[1]
        yield from bind_pat_arr(elems, v, env, st, 0, {})
    elif t == 'pobj':
        elems = pat[1]
        yield from bind_pat_obj(elems, v, env, st, 0, {})
    else:
        raise JQError('Invalid pattern')

def bind_pat_arr(elems, v, env, st, i, binds):
    if i >= len(elems):
        e = Env(env)
        e.vars.update(binds)
        yield e
        return
    val = index_num(v, float(i)) if isinstance(v, list) or v is None else (_for_err(v))
    for sub in bind_pat(elems[i], val, env, st):
        for sub2 in bind_pat_arr(elems, v, env, st, i + 1, dict(sub.vars if False else binds, **{k: sub.vars[k] for k in sub.vars if k not in binds})):
            yield sub2

def _for_err(v):
    raise JQError('Cannot index %s with number' % jq_type(v))

def bind_pat_obj(elems, v, env, st, i, binds):
    if i >= len(elems):
        e = Env(env)
        e.vars.update(binds)
        yield e
        return
    keyspec, pat = elems[i]
    if keyspec[0] == 's':
        key = keyspec[1]
        if v is None:
            val = None
        elif isinstance(v, dict):
            val = v.get(key)
        else:
            raise JQError('Cannot index %s with string "%s"' % (jq_type(v), key))
        for sub in bind_pat(pat, val, env, st):
            nb = dict(binds)
            nb.update(sub.vars)
            yield from bind_pat_obj(elems, v, env, st, i + 1, nb)
    elif keyspec[0] == 'b':
        # $var as key: binds the value at that key
        name = keyspec[1]
        if v is None:
            val = None
        elif isinstance(v, dict):
            if name not in v:
                raise JQError('Cannot index object with "%s"' % name)
            val = v[name]
        else:
            raise JQError('Cannot index %s with "%s"' % (jq_type(v), name))
        nb = dict(binds)
        nb[name] = val
        yield from bind_pat_obj(elems, v, env, st, i + 1, nb)
    else:
        for k in ev(keyspec[1], v, env, st):
            if v is None:
                val = None
            elif isinstance(v, dict):
                val = v.get(k)
            else:
                raise JQError('Cannot index %s with string' % jq_type(v))
            for sub in bind_pat(pat, val, env, st):
                nb = dict(binds)
                nb.update(sub.vars)
                yield from bind_pat_obj(elems, v, env, st, i + 1, nb)
PYEOF
echo ok"}

