                raise JQError('Cannot index %s with number' % jq_type(v))
            v = index_num(v, float(k))
        elif isinstance(k, dict) and 'start' in k:
            v = slice_value(v, k['start'], k['end'])
        else:
            raise JQError('Invalid path component')
