    if isinstance(k, str):
        if v is None:
            base = {}
        elif isinstance(v, dict):
            base = dict(v)
        else:
            raise JQError('Cannot index %s with "%s"' % (jq_type(v), k))
        base[k] = setpath_value(base.get(k), path[1:], newval)
        return base
