        if v is None:
            base = []
        elif isinstance(v, list):
            base = list(v)
        else:
            raise JQError('Cannot index %s with number' % jq_type(v))
        i = int(k)
        n = len(base)
        if i < 0:
            i += n
            if i < 0:
                raise JQError('Out of bounds negative array index')
        while len(base) <= i:
            base.append(None)
        base[i] = setpath_value(base[i], path[1:], newval)
        return base
    if isinstance(k, dict) and 'start' in k:
        if v is None:
            base = []
        elif isinstance(v, list):
            base = list(v)
        elif isinstance(v, str):
            base = v
        else:
            raise JQError('Cannot index %s with object' % jq_type(v))
        return setpath_slice(base, k['start'], k['end'], path[1:], newval)
    raise JQError('Invalid path component')

def setpath_slice(base, a, b, rest, newval):
    n = len(base)
    lo = 0 if a is None else int(math.floor(float(a)))
    hi = n if b is None else int(math.ceil(float(b)))
    if lo < 0:
        lo += n
    if hi < 0:
        hi += n
    lo = max(lo, 0)
    hi = min(hi, n)
    if isinstance(base, str):
        return base[:lo] + newval + base[hi:]
    sub = setpath_value(base[lo:hi], rest, newval)
    if not isinstance(sub, list):
        raise JQError('A slice of an array can only be assigned another array')
    return base[:lo] + sub + base[hi:]

def delpath_value(v, path):
    if not path:
        return None
    k = path[0]
    if v is None:
        return None
    if len(path) == 1:
        if isinstance(k, str):
            if not isinstance(v, dict):
                raise JQError('Cannot delete field at object')
            if k in v:
                r = dict(v)
                del r[k]
                return r
