        if isinstance(k, (int, float)):
            if not isinstance(v, list):
                raise JQError('Cannot delete field at array')
            i = int(k)
            n = len(v)
            if i < 0:
                i += n
            if i < 0 or i >= n:
                return v
            return v[:i] + v[i+1:]
        if isinstance(k, dict) and 'start' in k:
            if isinstance(v, str):
                n = len(v)
                lo = 0 if k['start'] is None else int(math.floor(float(k['start'])))
                hi = n if k['end'] is None else int(math.ceil(float(k['end'])))
                if lo < 0:
                    lo += n
                if hi < 0:
                    hi += n
                lo = max(lo, 0)
                hi = min(hi, n)
                return v[:lo] + v[hi:]
            if isinstance(v, list):
                n = len(v)
                lo = 0 if k['start'] is None else int(math.floor(float(k['start'])))
                hi = n if k['end'] is None else int(math.ceil(float(k['end'])))
                if lo < 0:
                    lo += n
                if hi < 0:
                    hi += n
                lo = max(lo, 0)
                hi = min(hi, n)
                return v[:lo] + v[hi:]
