        raise JQError('Invalid path component')
    if isinstance(k, str):
        if not isinstance(v, dict):
            raise JQError('Cannot index %s with "%s"' % (jq_type(v), k))
        if k not in v:
            return v
        r = dict(v)
        r[k] = delpath_value(r[k], path[1:])
        return r
    if isinstance(k, (int, float)):
        if not isinstance(v, list):
            raise JQError('Cannot index %s with number' % jq_type(v))
