            i += n
        if i < 0 or i >= n:
            return v
        r = list(v)
        r[i] = delpath_value(r[i], path[1:])
        return r
    raise JQError('Invalid path component')

def cmp_paths(a, b):
    # sort paths in jq's delpaths order (reverse lexicographic by index)
    return jq_cmp(a, b)

def ev_assign(node, inp, env, st):
    # E1 = E2: for each value of E2, set all paths
    paths = []
    try:
        for p, v in ev_paths(node[1], inp, env, st, []):
            paths.append(list(p))
    except NotPath as e:
        raise JQError('Invalid path expression with result %s' % dumpval(e.value))
    for v in ev(node[2], inp, env, st):
        r = inp
        for p in paths:
            r = setpath_value(r, p, v)
        yield r

def ev_update(node, inp, env, st, ):
    lhs, rhs, op = node[1], node[2], node[3]
    # compute paths in order
    try:
        pairs = list(ev_paths(lhs, inp, env, st, []))
    except NotPath as e:
        raise JQError('Invalid path expression with result %s' % dumpval(e.value))
    r = inp
    for p, old in pairs:
        if op == '|=':
            vals = list(ev(rhs, old, env, st))
            if not vals:
                r = delpath_value(r, p)
            else:
                r = setpath_value(r, p, vals[0])
        else:
            for v in ev(rhs, inp, env, st):
