            yield r

def fromstream_one(stream):
    """stream is a list of stream events"""
    if not isinstance(stream, list):
        raise JQError('fromstream: stream must be an array')
    return fromstream_gen(stream)

def fromstream_gen(events):
    stack = []
    result = []
    cur = []
    started = False
    i = 0
    n = len(events)
    while i < n:
        e = events[i]
        i += 1
        if not isinstance(e, list):
            raise JQError('fromstream: invalid event')
        if len(e) == 2:
            path, val = e
            if len(path) == len(cur):
                # scalar at current level
                if path != cur:
                    raise JQError('fromstream: invalid path')
                result.append(val)
                continue
            if len(path) < len(cur):
                # close levels
                while len(cur) > len(path) + 1:
                    cur.pop()
                cur.pop()
            if len(path) > len(cur):
                # open levels
                pass
            cur = list(path)
            stack = []
            stack.append(val)
            started = True
        elif len(e) == 1:
            path = e[0]
            if len(path) <= len(cur):
                # close
                while len(cur) > len(path):
                    cur.pop()
                if len(cur) == len(path):
                    v = stack.pop()
                    # attach to parent
                    if stack:
                        parent = stack[-1]
                        stack[-1] = attach(parent, cur[-1], v)
                    else:
                        result.append(v)
                    cur.pop()
                    continue
            cur = list(path)
            stack.append(None)
            started = True
        else:
            raise JQError('fromstream: invalid event')
    if stack:
        result.append(stack[0])
    for r in result:
        yield r

def attach(container, key, val):
    if isinstance(container, dict):
        r = dict(container)
        r[key] = val
        return r
    if isinstance(container, list):
        r = list(container)
        while len(r) <= key:
            r.append(None)
        r[key] = val
        return r
    return {key: val}

