def compile_regex(re_s, flags_s, inp=None):
    if not isinstance(re_s, str):
        raise JQError('%s (%s) cannot be matched, as it is not a string' % (jq_type(inp), dumpval(inp)))
    if not isinstance(flags_s, str):
        raise JQError('%s (%s) is not a string' % (jq_type(flags_s), dumpval(flags_s)))
