    global_ = False
    ignore_empty = False
    for ch in flags_s:
        if ch == 'g':
            global_ = True
        elif ch == 'i':
            f |= _re_mod.I
        elif ch == 'x':
            f |= _re_mod.X
        elif ch == 's':
            f |= _re_mod.S
        elif ch == 'm':
            f |= _re_mod.M
        elif ch == 'n':
