    caps = []
    gi = m.re.groupindex
    names = {}
    for name, idx in gi.items():
        names[idx] = name
    for i in range(1, (m.re.groups if hasattr(m.re, 'groups') else m.re.groups) + 1):
        try:
            g = m.group(i)
        except Exception:
            g = None
        if g is None:
            caps.append({'offset': -1, 'length': 0, 'string': None, 'name': names.get(i)})
        else:
            st = m.start(i)
            caps.append({'offset': float(st), 'length': float(len(g)),
