    mo = int(arr[1]) if len(arr) > 1 else 0
    d = int(arr[2]) if len(arr) > 2 else 0
    h = int(arr[3]) if len(arr) > 3 else 0
    mi = int(arr[4]) if len(arr) > 4 else 0
    s = int(arr[5]) if len(arr) > 5 else 0
    days = _civil_days(y, mo + 1, d)
    wd = (days + 4) % 7
    yd = days - _civil_days(y, 1, 1)
    return [y, mo, d, h, mi, s, wd, yd, days]

def _strftime(fmt, tm, local=False):
    out = []
    i = 0
    n = len(fmt)
    y, mo, d, h, mi, s, wd, yd, days = tm
    epoch = days * 86400 + h * 3600 + mi * 60 + s
    while i < n:
        c = fmt[i]
        if c != '%':
            out.append(c)
            i += 1
            continue
        i += 1
        if i >= n:
            out.append('%')
            break
        sp = fmt[i]
        i += 1
        if sp == 'a':
            out.append(WDAY_AB[wd % 7])
        elif sp == 'A':
            out.append(WDAY_NAMES[wd % 7])
        elif sp == 'b' or sp == 'h':
            out.append(MONTH_AB[mo] if 0 <= mo < 12 else '')
        elif sp == 'B':
            out.append(MONTH_NAMES[mo] if 0 <= mo < 12 else '')
        elif sp == 'c':
            out.append(_strftime('%a %b %e %H:%M:%S %Y', tm, local))
        elif sp == 'C':
            out.append('%C')
        elif sp == 'd':
            out.append('%02d' % d)
        elif sp == 'D':
            out.append('%D')
        elif sp == 'e':
            out.append('%2d' % d)
        elif sp == 'F':
            out.append(_strftime('%Y-%m-%d', tm, local))
        elif sp == 'g':
            out.append('%g')
        elif sp == 'G':
            iso = iso_week(tm)
            out.append('%04d' % iso[0])
        elif sp == 'H':
            out.append('%02d' % h)
        elif sp == 'I':
            out.append('%I')
        elif sp == 'j':
            out.append('%03d' % (yd + 1))
        elif sp == 'k':
            out.append('%2d' % h)
        elif sp == 'l':
            h12 = h % 12
            if h12 == 0:
                h12 = 12
            out.append('%2d' % h12)
        elif sp == 'm':
            out.append('%02d' % (mo + 1))
        elif sp == 'M':
            out.append('%02d' % mi)
        elif sp == 'n':
            out.append('\n')
        elif sp == 'p':
            out.append('AM' if h < 12 else 'PM')
        elif sp == 'P':
            out.append('am' if h < 12 else 'pm')
        elif sp == 'r':
            out.append(_strftime('%I:%M:%S %p', tm, local))
        elif sp == 'R':
            out.append('%R')
        elif sp == 's':
            out.append(str(epoch))
        elif sp == 'S':
            out.append('%02d' % s)
        elif sp == 't':
            out.append('\t')
        elif sp == 'T':
            out.append(_strftime('%H:%M:%S', tm, local))
        elif sp == 'u':
            out.append(str((wd % 7 - 1) % 7 + 1))
        elif sp == 'U':
            out.append('%02d' % ((yd + 7 - wd) // 7))
        elif sp == 'V':
            out.append('%02d' % iso_week(tm)[1])
        elif sp == 'v':
            out.append('%v')
        elif sp == 'w':
            out.append(str(wd % 7))
        elif sp == 'W':
            out.append('%02d' % ((yd + 7 - ((wd + 6) % 7)) // 7))
        elif sp == 'x':
            out.append(_strftime('%m/%d/%y', tm, local))
        elif sp == 'X':
            out.append(_strftime('%H:%M:%S', tm, local))
        elif sp == 'y':
            out.append('%02d' % (y % 100))
        elif sp == 'Y':
            out.append('%d' % y)
        elif sp == 'z':
            if local:
                off = -_time.timezone
                if _time.daylight:
                    off = -_time.altzone
                sign = '+' if off >= 0 else '-'
                a = abs(off)
                out.append('%s%02d%02d' % (sign, a // 3600, (a % 3600) // 60))
            else:
                out.append('+0000')
        elif sp == 'Z':
            if local:
                out.append(_time.tzname[0] if _time.tzname else 'GMT')
            else:
                out.append('GMT')
        elif sp == '%':
            out.append('%')
        else:
            out.append('%' + sp)
    return ''.join(out)

def iso_week(tm):
    y, mo, d, h, mi, s, wd, yd, days = tm
    # ISO 8601 week number
    wday = (wd % 7 - 1) % 7 + 1  # 1=Monday
    yy = y
    doy = yd + 1
    # Thursday of this week
    iso_y = y
    week = ((doy - wday + 10) // 7)
    if week < 1:
        iso_y -= 1
        week = ((doy + 365 + (366 if _is_leap(iso_y) else 0) - wday + 10) // 7)
    elif week > 52:
        if week > ((365 if not _is_leap(y) else 366) - wday + 10) // 7:
            iso_y += 1
            week = 1
    return (iso_y, week)

def _is_leap(y):
    return (y % 4 == 0 and y % 100 != 0) or y % 400 == 0

