def parse_strptime(s, fmt):
    y = mo = d = h = mi = sec = 0
    got = set()
    i = 0
    j = 0
    n = len(fmt)
    pm = None
    while i < n:
        c = fmt[i]
        if c == '%':
            i += 1
            if i >= n:
                break
            sp = fmt[i]
            i += 1
            if sp == 'Y':
                val, j = _scan_num(s, j, 4, False)
                if val is None:
                    raise JQError('date "%s" does not match format "%s"' % (s, fmt))
                y = val
                got.add('y')
            elif sp == 'y':
                val, j = _scan_num(s, j, 2, False)
                if val is None:
                    raise JQError('date "%s" does not match format "%s"' % (s, fmt))
                y = val + (1900 if val >= 69 else 2000)
                got.add('y')
            elif sp == 'm':
                val, j = _scan_num(s, j, 2, False)
                if val is None or not (1 <= val <= 12):
                    raise JQError('date "%s" does not match format "%s"' % (s, fmt))
                mo = val - 1
                got.add('m')
            elif sp == 'd' or sp == 'e':
                val, j = _scan_num(s, j, 2, True)
                if val is None or not (1 <= val <= 31):
                    raise JQError('date "%s" does not match format "%s"' % (s, fmt))
                d = val
                got.add('d')
            elif sp == 'H' or sp == 'k':
                val, j = _scan_num(s, j, 2, True)
                if val is None or not (0 <= val <= 23):
                    raise JQError('date "%s" does not match format "%s"' % (s, fmt))
                h = val
                got.add('H')
            elif sp == 'I' or sp == 'l':
                val, j = _scan_num(s, j, 2, True)
                if val is None:
                    raise JQError('date "%s" does not match format "%s"' % (s, fmt))
                h = val % 12
                if pm is not None:
                    h += pm
                got.add('H')
            elif sp == 'M':
                val, j = _scan_num(s, j, 2, False)
                if val is None or not (0 <= val <= 59):
                    raise JQError('date "%s" does not match format "%s"' % (s, fmt))
                mi = val
                got.add('M')
            elif sp == 'S':
                val, j = _scan_num(s, j, 2, False)
                if val is None or not (0 <= val <= 60):
                    raise JQError('date "%s" does not match format "%s"' % (s, fmt))
                sec = val
                got.add('S')
            elif sp == 'j':
                val, j = _scan_num(s, j, 3, False)
                if val is None:
                    raise JQError('date "%s" does not match format "%s"' % (s, fmt))
                got.add('j')
                yd = val
