                    pm = 0
                    j += 2
                elif s[j:j+2].upper() == 'PM':
                    pm = 12
                    j += 2
                else:
                    raise JQError('date "%s" does not match format "%s"' % (s, fmt))
            elif sp == 'Z':
                if s[j:j+3] == 'GMT' or s[j:j+3] == 'UTC' or s[j:j+3] == 'UT':
                    j += 3
                elif s[j:j+1] == 'Z':
                    j += 1
                else:
                    raise JQError('date "%s" does not match format "%s"' % (s, fmt))
            elif sp == 'z':
                k = j
                if k < len(s) and s[k] in '+-':
                    k += 1
                    cnt = 0
                    while k < len(s) and s[k].isdigit():
                        k += 1
