                y, mo, d, h, mi, sec = _unpack_epoch(val)
                got.update(['y', 'm', 'd', 'H', 'M', 'S'])
            elif sp == 'c':
                for sub in ('%a', ' ', '%b', ' ', '%e', ' ', '%H', ':', '%M', ':', '%S', ' ', '%Y'):
                    if sub in ('%a', '%b', '%e', '%H', '%M', '%S', '%Y'):
                        tm2, _ = parse_strptime(s[j:], sub)
                        j += 1
                    else:
                        if j < len(s) and s[j] == sub:
                            j += 1
                got.update(['y', 'm', 'd', 'H', 'M', 'S'])
            elif sp == 'x':
                for sub in ('%m', '/', '%d', '/', '%y'):
                    tm2, _ = parse_strptime(s[j:], sub)
                    j += 1
                got.update(['y', 'm', 'd'])
            elif sp == 'X':
                for sub in ('%H', ':', '%M', ':', '%S'):
                    tm2, _ = parse_strptime(s[j:], sub)
                    j += 1
