            elif sp == 'T':
                for sub in ('%H', ':', '%M', ':', '%S'):
                    tm2, _ = parse_strptime(s[j:], sub)
                    j += 1
                got.update(['H', 'M', 'S'])
            elif sp == 'D':
                for sub in ('%m', '/', '%d', '/', '%y'):
                    tm2, _ = parse_strptime(s[j:], sub)
                    j += 1
            elif sp == 'F':
                for sub in ('%Y', '-', '%m', '-', '%d'):
                    tm2, _ = parse_strptime(s[j:], sub)
                    j += 1
                got.update(['y', 'm', 'd'])
            elif sp == 'R':
                for sub in ('%H', ':', '%M', ':', '%S'):
                    tm2, _ = parse_strptime(s[j:], sub)
                    j += 1
            elif sp == 'r':
                for sub in ('%I', ':', '%M', ':', '%S', ' ', '%p'):
                    tm2, _ = parse_strptime(s[j:], sub)
                    j += 1
            elif sp == '%':
                if j < len(s) and s[j] == '%':
                    j += 1
