                j += 1
                i += 1
            else:
                raise JQError('date "%s" does not match format "%s"' % (s, fmt))
    if j != len(s):
        pass
    if pm is not None and 'H' in got and h < 12 and pm == 12:
        pass
    if pm is not None:
        h = h % 12 + pm
    days = _civil_days(y, mo + 1, d)
    wd = (days + 4) % 7
    yd = days - _civil_days(y, 1, 1)
    return [y, mo, d, h, mi, sec, wd, yd], s[j:]

def _unpack_epoch(v):
    days = v // 86400
    rem = v - days * 86400
    y, m, d = _days_to_civil(days)
    return (y, m - 1, d, rem // 3600, (rem % 3600) // 60, rem % 60)

def _scan_num(s, j, maxlen, skipws):
    if skipws:
        while j < len(s) and s[j] == ' ':
            j += 1
    k = j
    cnt = 0
    while k < len(s) and s[k].isdigit() and cnt < maxlen:
        k += 1
        cnt += 1
    if cnt == 0:
        return None, j
    return int(s[j:k]), k

def _match_name(s, j, names):
    best = None
    for i, nm in enumerate(names):
        if s.startswith(nm, j):
            if best is None or len(nm) > len(names[best]):
                best = i
    return best

