def emit(out, v, st):
    opts = st.opts
    dopts = st.dump_opts
    if opts['raw_output'] and isinstance(v, str):
        if opts['ascii_output']:
            s = raw_string(v, True)
        else:
            s = v
        if opts['raw_output0']:
            out.write(s + '\0')
        elif opts['join_output']:
            out.write(s)
        else:
            out.write(s + '\n')
        return
    parts = []
    if opts['seq']:
        parts.append('\x1e')
    jv_dump(v, dopts, 0, parts)
    s = ''.join(parts)
    if opts['seq'] or not opts['join_output']:
        s += '\n'
    if opts['raw_output0']:
        s = s[:-1] + '\0' if s.endswith('\n') else s
    out.write(s)

def make_inputs(st, opts, files):
    """Generator of input values."""
    if opts['null_input']:
        return
