                sys.stderr.write('jq: error: Could not open file %s: %s\n' % (f, e.strerror))
                sys.exit(2)
            datas.append((f, data))
    else:
        data = sys.stdin.buffer.read()
        datas.append((None, data))
    for fname, data in datas:
        st.input_filename = fname if fname is not None else '<stdin>'
        if opts['raw_input']:
            for line in data.decode('utf-8', 'surrogateescape').split('\n'):
                if line.endswith('\r'):
                    line = line[:-1]
                st.raw_lines = True
                yield line
            continue
        if opts['seq']:
            for v, line_no in seq_values(data, st):
                st.input_line_number = line_no
