def stream_values(data, st, as_errors):
    chars, blen = utf8_chars(data)
    p = StreamParser()
    n = len(chars)
    for i in range(n):
        ch = chars[i]
        p.col += blen[i]
        if ch == '\n':
            p.line += 1
            p.col = 0
        try:
            p.process(ch)
        except ParseError as e:
            if as_errors:
                yield ['%s%s at line %d, column %d' % (e.msg, ' at EOF' if e.eof else '', e.line, e.col), []]
                return
            raise
        if p.out:
            for e in p.out:
                yield e
            p.out = []
    try:
        p.finish()
    except ParseError as e:
        if as_errors:
            yield ['%s%s at line %d, column %d' % (e.msg, ' at EOF' if e.eof else '', e.line, e.col), []]
            return
        raise
    if p.out:
        for e in p.out:
            yield e
        p.out = []

def seq_values(data, st):
    chars, blen = utf8_chars(data)
    n = len(chars)
    i = 0
    rs_seen = False
    pending_text = False
    p = None
    while i < n:
        ch = chars[i]
        if ch == '\x1e':
            rs_seen = True
            pending_text = False
            p = JvParser(False)
            i += 1
            continue
        if not rs_seen:
            pending_text = True
            if p is None:
                p = JvParser(False)
            p.col += blen[i]
            if ch == '\n':
                p.line += 1
                p.col = 0
            i += 1
            continue
        try:
            p.col += blen[i]
            if ch == '\n':
                p.line += 1
                p.col = 0
            p.process(ch)
        except ParseError as e:
            sys.stderr.write('jq: ignoring parse error: %s%s at line %d, column %d (need RS to resync)\n'
                             % (e.msg, ' at EOF' if e.eof else '', e.line, e.col))
            sys.stderr.flush()
            rs_seen = False
            pending_text = False
            p = None
            i += 1
            continue
        if p.out:
            for v in p.out:
                st.input_line_number = p.line
                yield v
            p.out = []
        i += 1
    if rs_seen:
        try:
            p.flush_token(True)
            if p.frames:
                raise ParseError('Unfinished JSON term', p.line, p.col, True)
            for v in p.out:
                st.input_line_number = p.line
                yield v
        except ParseError as e:
            if e.msg == 'Potentially truncated top-level numeric value':
                sys.stderr.write('jq: ignoring parse error: %s at EOF at line %d, column %d\n'
                                 % (e.msg, e.line, e.col))
            else:
                sys.stderr.write('jq: ignoring parse error: %s%s at line %d, column %d\n'
                                 % (e.msg, ' at EOF' if e.eof else '', e.line, e.col))
            sys.stderr.flush()
    elif pending_text:
        sys.stderr.write('jq: ignoring parse error: Unfinished abandoned text at EOF at line %d, column %d\n'
