class StreamParser:
    __slots__ = ('line', 'col', 'st', 'token', 'stack', 'cur', 'out', 'strbuf',
                 'strerr', 'unic', 'unival', 'hi_pending', 'hi_val', 'topdone')

    def __init__(self):
        self.line = 1
        self.col = 0
        self.st = 0
        self.token = []
        self.stack = []       # frames: ['a', idx, lastpath, path] / ['o', key, lastpath, path]
        self.cur = []         # path where the next value goes
        self.out = []
        self.strbuf = []
        self.strerr = None
        self.unic = 0
        self.unival = 0
        self.hi_pending = False
        self.hi_val = 0

    def value(self, v):
        if not self.stack:
            self.out.append([list(self.cur), v])
            return
        fr = self.stack[-1]
        if fr[0] == 'a':
            p = list(self.cur)
            self.out.append([p, v])
            fr[1] += 1
            fr[2] = p
            self.cur = fr[3] + [fr[1]]
        else:
            if fr[1] is None:
                if jq_type(v) != 'string':
                    raise ParseError('Object keys must be strings', self.line, self.col, False)
                fr[1] = v
                self.cur = fr[3] + [v]
            else:
                p = list(self.cur)
                self.out.append([p, v])
                fr[2] = p
                fr[1] = None
                self.cur = fr[3]

    def delim(self, ch):
        if not self.stack:
            if ch == '{':
                self.stack.append(['o', None, None, list(self.cur)])
                self.cur = list(self.cur)
                return
            if ch == '[':
                self.stack.append(['a', 0, None, list(self.cur)])
                self.cur = self.cur + [0]
                return
            if ch == ',':
                raise ParseError("Expected value before ','", self.line, self.col, False)
            if ch == ']':
                raise ParseError("Unmatched ']'", self.line, self.col, False)
            if ch == '}':
                raise ParseError("Unmatched '}'", self.line, self.col, False)
            raise ParseError("Expected value before ','", self.line, self.col, False)
        fr = self.stack[-1]
        if fr[0] == 'a':
            if ch == ',':
                return
            if ch == ']':
                self.close(fr)
            elif ch == '{':
                self.stack.append(['o', None, None, list(self.cur)])
            elif ch == '[':
                self.stack.append(['a', 0, None, list(self.cur)])
                self.cur = self.cur + [0]
            elif ch == ':':
                raise ParseError("Expected value before ','", self.line, self.col, False)
            else:
                raise ParseError('Expected separator between values', self.line, self.col, False)
        else:
            if ch == ':':
