                    raise ParseError('Expected separator between values', self.line, self.col, False)
            else:
                raise ParseError('Expected separator between values', self.line, self.col, False)

    def close(self, fr):
        self.stack.pop()
        p = fr[3]
        if fr[0] == 'a':
            val = []
        else:
            val = {}
        if fr[2] is None:
            # empty container
            self.cur = list(p)
            self.out.append([list(p), val])
        else:
            self.out.append([list(fr[2])])
            self.cur = list(p)
        if self.stack:
            pfr = self.stack[-1]
            if pfr[0] == 'a':
                self.cur = pfr[3] + [pfr[1]]
            else:
                if pfr[1] is None:
                    self.cur = list(pfr[3])
                else:
                    self.cur = list(pfr[3])
        else:
            self.cur = []

    def process(self, ch):
