            self.strbuf = []
            self.strerr = None
            self.hi_pending = False
            self.unic = 0
            self.unival = 0
            return
        if ch in _WHITESPACE:
            self.flush_token()
            return
        if ch in _DELIMS:
            self.flush_token()
            self.delim(ch)
            return
        self.token.append(ch)

    def add_uni(self):
        cp = self.unival
        self.unic = 0
        self.unival = 0
