        data = sys.stdin.buffer.read()
        datas.append((None, data))
    for fname, data in datas:
        st.input_filename = fname if fname is not None else '<stdin>'
        if opts['raw_input']:
            text = data.decode('utf-8', 'surrogateescape')
            lines = text.split('\n')
            if lines and lines[-1] == '':
                lines.pop()
            for line in lines:
                if line.endswith('\r'):
                    line = line[:-1]
                st.input_line_number += 1
                yield line
            continue
        if opts['seq']:
            for v in seq_values(data, st):
                yield v
            continue
        if opts['stream']:
            for e in stream_values(data, st, opts['stream_errors']):
                yield e
            continue
        for v in json_values(data):
            yield v

def stream_values(data, st, as_errors):
    chars, blen = utf8_chars(data)
    p = StreamParser()
    n = len(chars)
    for i in range(n):
        ch = chars[i]
        p.col += blen[i]
        if ch == '\n':
            p.line += 1
            p.col = 0
        try:
            p.process(ch)
        except ParseError as e:
            if as_errors:
                yield ['%s%s at line %d, column %d' % (e.msg, ' at EOF' if e.eof else '', e.line, e.col), []]
                return
            raise
        if p.out:
            for e in p.out:
                yield e
            p.out = []
    try:
        p.finish()
    except ParseError as e:
        if as_errors:
            yield ['%s%s at line %d, column %d' % (e.msg, ' at EOF' if e.eof else '', e.line, e.col), []]
            return
        raise
    if p.out:
        for e in p.out:
            yield e
        p.out = []

def seq_values(data, st):
    chars, blen = utf8_chars(data)
    n = len(chars)
    i = 0
    rs_seen = False
    pending_text = False
    p = None
    while i < n:
        ch = chars[i]
        if ch == '\x1e':
            rs_seen = True
            pending_text = False
            p = JvParser(False)
            i += 1
            continue
        if not rs_seen:
            pending_text = True
            if p is None:
                p = JvParser(False)
            p.col += blen[i]
            if ch == '\n':
                p.line += 1
                p.col = 0
            i += 1
            continue
        try:
            p.col += blen[i]
            if ch == '\n':
                p.line += 1
                p.col = 0
            p.process(ch)
        except ParseError as e:
            sys.stderr.write('jq: ignoring parse error: %s%s at line %d, column %d (need RS to resync)\n'
                             % (e.msg, ' at EOF' if e.eof else '', e.line, e.col))
            sys.stderr.flush()
            rs_seen = False
            pending_text = False
            p = None
            i += 1
            continue
        if p.out:
            for v in p.out:
                st.input_line_number = p.line
                yield v
            p.out = []
        i += 1
    if rs_seen:
        try:
            p.flush_token(True)
            if p.frames:
                raise ParseError('Unfinished JSON term', p.line, p.col, True)
            for v in p.out:
                st.input_line_number = p.line
                yield v
        except ParseError as e:
            if e.msg == 'Potentially truncated top-level numeric value':
                sys.stderr.write('jq: ignoring parse error: %s at EOF at line %d, column %d\n'
                                 % (e.msg, e.line, e.col))
            else:
                sys.stderr.write('jq: ignoring parse error: %s%s at line %d, column %d\n'
                                 % (e.msg, ' at EOF' if e.eof else '', e.line, e.col))
            sys.stderr.flush()
    elif pending_text:
        sys.stderr.write('jq: ignoring parse error: Unfinished abandoned text at EOF at line %d, column %d\n'
                         % (p.line, p.col))
        sys.stderr.flush()

class StreamParser:
    __slots__ = ('line', 'col', 'st', 'token', 'stack', 'cur', 'out', 'strbuf',
                 'strerr', 'unic', 'unival', 'hi_pending', 'hi_val', 'topdone')

    def __init__(self):
        self.line = 1
        self.col = 0
        self.st = 0
        self.token = []
        self.stack = []       # frames: ['a', idx, lastpath, path] / ['o', key, lastpath, path]
        self.cur = []         # path where the next value goes
        self.out = []
        self.strbuf = []
        self.strerr = None
        self.unic = 0
        self.unival = 0
        self.hi_pending = False
        self.hi_val = 0

    def value(self, v):
        if not self.stack:
            self.out.append([list(self.cur), v])
            return
        fr = self.stack[-1]
        if fr[0] == 'a':
            p = list(self.cur)
            self.out.append([p, v])
            fr[1] += 1
            fr[2] = p
            self.cur = fr[3] + [fr[1]]
        else:
            if fr[1] is None:
                if jq_type(v) != 'string':
                    raise ParseError('Object keys must be strings', self.line, self.col, False)
                fr[1] = v
                self.cur = fr[3] + [v]
            else:
                p = list(self.cur)
                self.out.append([p, v])
                fr[2] = p
                fr[1] = None
                self.cur = fr[3]

    def delim(self, ch):
        if not self.stack:
            if ch == '{':
                self.stack.append(['o', None, None, list(self.cur)])
                self.cur = list(self.cur)
                return
            if ch == '[':
                self.stack.append(['a', 0, None, list(self.cur)])
                self.cur = self.cur + [0]
                return
            if ch == ',':
                raise ParseError("Expected value before ','", self.line, self.col, False)
            if ch == ']':
                raise ParseError("Unmatched ']'", self.line, self.col, False)
            if ch == '}':
                raise ParseError("Unmatched '}'", self.line, self.col, False)
            raise ParseError("Expected value before ','", self.line, self.col, False)
        fr = self.stack[-1]
        if fr[0] == 'a':
            if ch == ',':
                return
            if ch == ']':
                self.close(fr)
            elif ch == '{':
                self.stack.append(['o', None, None, list(self.cur)])
            elif ch == '[':
                self.stack.append(['a', 0, None, list(self.cur)])
                self.cur = self.cur + [0]
            elif ch == ':':
                raise ParseError("Expected value before ','", self.line, self.col, False)
            else:
                raise ParseError('Expected separator between values', self.line, self.col, False)
        else:
            if ch == ':':
                if fr[1] is None:
                    raise ParseError('Object keys must be strings', self.line, self.col, False)
                return
            if ch == ',':
                if fr[1] is None:
                    raise ParseError("Expected value before ','", self.line, self.col, False)
                fr[1] = None
                self.cur = fr[3]
                return
            if ch == '}':
                self.close(fr)
            elif ch == '{':
                if fr[1] is None:
                    self.stack.append(['o', None, None, list(self.cur)])
                else:
                    raise ParseError('Expected separator between values', self.line, self.col, False)
            elif ch == '[':
                if fr[1] is None:
                    self.stack.append(['a', 0, None, list(self.cur)])
                    self.cur = self.cur + [0]
                else:
                    raise ParseError('Expected separator between values', self.line, self.col, False)
            else:
                raise ParseError('Expected separator between values', self.line, self.col, False)

    def close(self, fr):
        self.stack.pop()
        p = fr[3]
        if fr[0] == 'a':
            val = []
        else:
            val = {}
        if fr[2] is None:
            # empty container
            self.cur = list(p)
            self.out.append([list(p), val])
        else:
            self.out.append([list(fr[2])])
            self.cur = list(p)
        if self.stack:
            pfr = self.stack[-1]
            if pfr[0] == 'a':
                self.cur = pfr[3] + [pfr[1]]
            else:
                if pfr[1] is None:
                    self.cur = list(pfr[3])
                else:
                    self.cur = list(pfr[3])
        else:
            self.cur = []

    def process(self, ch):
        st = self.st
        if st == 1:
            if ch == '\\':
                self.st = 2
                return
            if ch == '"':
                self.finish_string()
                return
            if ord(ch) < 0x20:
                if self.strerr is None:
                    self.strerr = 'Invalid string: control characters from U+0000 through U+001F must be escaped'
                self.strbuf.append(ch)
                return
            if self.hi_pending and self.strerr is None:
                self.strerr = 'Invalid \\uXXXX\\uXXXX surrogate pair escape'
            self.strbuf.append(ch)
            return
        if st == 2:
            if ch == 'u':
                self.st = 3
                self.unic = 0
                self.unival = 0
                return
            self.st = 1
            if ch in STR_ESC:
                if self.hi_pending and self.strerr is None:
                    self.strerr = 'Invalid \\uXXXX\\uXXXX surrogate pair escape'
                self.strbuf.append(STR_ESC[ch])
            else:
                if self.strerr is None:
                    self.strerr = 'Invalid escape'
            return
        if st == 3:
            if ch in HEXDIG:
                self.unival = self.unival * 16 + int(ch, 16)
                self.unic += 1
                if self.unic == 4:
                    self.add_uni()
                return
            if self.strerr is None:
                self.strerr = 'Invalid characters in \\uXXXX escape'
            self.st = 1
            return
        if ch == '"':
            self.flush_token()
            self.st = 1
            self.strbuf = []
            self.strerr = None
            self.hi_pending = False
            self.unic = 0
            self.unival = 0
            return
        if ch in _WHITESPACE:
            self.flush_token()
            return
        if ch in _DELIMS:
            self.flush_token()
            self.delim(ch)
            return
        self.token.append(ch)

    def add_uni(self):
        cp = self.unival
        self.unic = 0
        self.unival = 0
        if self.hi_pending:
            if 0xdc00 <= cp <= 0xdfff:
                cp = 0x10000 + self.hi_val + (cp - 0xdc00)
                self.hi_pending = False
                self.strbuf.append(chr(cp))
                self.st = 1
            else:
                if self.strerr is None:
                    self.strerr = 'Invalid \\uXXXX\\uXXXX surrogate pair escape'
                self.st = 1
            return
        if 0xd800 <= cp <= 0xdbff:
            self.hi_pending = True
            self.hi_val = (cp - 0xd800) << 10
            self.st = 1
            return
        if 0xdc00 <= cp <= 0xdfff:
            cp = 0xfffd
        self.strbuf.append(chr(cp))
        self.st = 1

    def finish_string(self):
        self.st = 0
        if self.strerr is not None:
            raise ParseError(self.strerr, self.line, self.col, False)
        if self.hi_pending:
            raise ParseError('Invalid \\uXXXX\\uXXXX surrogate pair escape', self.line, self.col, False)
        if self.unic:
            raise ParseError('Invalid \\uXXXX escape', self.line, self.col, False)
        s = ''.join(self.strbuf)
        self.strbuf = []
        self.hi_pending = False
        self.value(s)

    def flush_token(self, eof=False):
        if not self.token:
            return
        tok = ''.join(self.token)
        self.token = []
        if tok == 'true':
            v = True
        elif tok == 'false':
            v = False
        elif tok == 'null':
            v = None
        else:
            low = tok.lower()
            if low == 'nan':
                v = float('nan')
            elif low == 'inf' or low == 'infinity':
                v = float('inf')
            elif low == '-inf' or low == '-infinity':
                v = float('-inf')
            elif _NUM_RE.match(tok):
                v = parse_number_literal(tok)
            else:
                if tok[0] == 't' or tok[0] == 'f' or (tok[0] == 'n' and len(tok) > 1 and tok[1] == 'u'):
                    raise ParseError('Invalid literal', self.line, self.col, eof)
                raise ParseError('Invalid numeric literal', self.line, self.col, eof)
        self.value(v)

    def finish(self):
        if self.st != 0:
            raise ParseError('Unfinished string', self.line, self.col, True)
        self.flush_token(True)
        if self.stack:
            raise ParseError('Unfinished JSON term', self.line, self.col, True)

def run_main(st, ast, env, out):
    opts = st.opts
    saw = False
    falsy = False
    inputs = st.inputs
    for inp in inputs:
        if opts['raw_input']:
            st.input_line_number = st.input_line_number
        try:
            for v in ev(ast, inp, env, st):
                emit(out, v, st)
                saw = True
                falsy = not truthy(v)
                if opts['unbuffered']:
                    out.flush()
        except JQError as e:
            out.flush()
            raise
    st.saw_output = saw
    st.last_falsy = falsy

def main_entry(argv):
    try:
        opts, named, positional, program, files = parse_args(argv)
    except SystemExit:
        raise
    st = JqState()
    st.opts = opts
    st.jq_origin = '.'
    try:
        st.prog_origin = os.path.dirname(os.path.abspath(argv[0])) or '.'
    except Exception:
        st.prog_origin = '.'
    st.search_list = ['~/.jq', '$ORIGIN/../lib/jq', '$ORIGIN/../lib']
    for p in reversed(opts['library_path']):
        st.search_list.insert(0, p)
    st.env = dict(os.environ)
    st.named = named
    st.positional = positional
    st.exit_status = opts['exit_status']
    st.prog_filename = '<top-level>'
    indent = opts['indent']
    if opts['tab']:
        indent = -1
    if opts['monochrome']:
        color = False
    elif opts['color_output']:
        color = True
    else:
        color = False
    st.dump_opts = DumpOpts(compact=opts['compact'], tab=opts['tab'],
                            indent=indent, sort_keys=opts['sort_keys'],
                            color=color, ascii_out=opts['ascii_output'])
    if opts['from_file']:
        try:
            src = read_text_file(opts['from_file'])
        except OSError as e:
            sys.stderr.write('jq: error: Could not open %s: %s\n' % (opts['from_file'], e.strerror))
            return 2
        st.prog_filename = opts['from_file']
    else:
        if program is None:
            sys.stdout.write(USAGE_SHORT)
            return 2
        src = program
    st.src = src
    errors = []
    ast = None
    try:
        toks = lex(src)
        p = Parser(toks, src, st.prog_filename)
        ast = p.parse_program()
    except JqSyntax as e:
        errors.append(e)
    except _LexStr as e:
        errors.append(('lexstr', e))
    except Exception as e:
        errors.append(('other', e))
    if errors:
        return report_compile_errors(errors, st)
    env = Env(None)
    env.vars['ENV'] = dict(st.env)
    env.vars['ARGS'] = {'positional': list(positional), 'named': dict(named)}
    for k, v in named.items():
        env.vars[k] = v
    env.vars['__loc__'] = {'file': st.prog_filename, 'line': 1}
    st.prog_line = 1
    out = sys.stdout
    try:
        st.inputs = make_inputs(st, opts, files)
        run_main(st, ast, env, out)
    except Halt as h:
        out.flush()
        return h.code
    except HaltError as h:
        out.flush()
        write_halt_error(h)
        return h.code
    except JQError as e:
        out.flush()
        sys.stderr.write('jq: error (at %s): %s\n' % (error_loc(st), error_msg(e.value)))
        return 5
    except Break as b:
        out.flush()
        sys.stderr.write('jq: error (at %s): %s\n' % (error_loc(st), b.name))
        return 5
    except ParseError as e:
        out.flush()
        sys.stderr.write('jq: parse error: %s%s at line %d, column %d\n'
                         % (e.msg, ' at EOF' if e.eof else '', e.line, e.col))
        return 5
    except CompileError as e:
        out.flush()
        sys.stderr.write('jq: error: %s\n' % str(e))
        return 3
    except OSError as e:
        out.flush()
        sys.stderr.write('jq: error: %s\n' % str(e))
        return 2
    out.flush()
    if opts['exit_status']:
        if not st.saw_output:
            return 4
        if st.last_falsy:
            return 1
    return 0

if __name__ == '__main__':
    sys.setrecursionlimit(20000)
    try:
        rc = main_entry(sys.argv[1:])
    except BrokenPipeError:
        rc = 2
    except KeyboardInterrupt:
        rc = 2
    sys.exit(rc)
