new = '''def make_inputs(st, opts, files):
    if opts['null_input']:
        yield None
        return
    datas = []
    if files:
        for f in files:
            try:
                data = read_bytes_file(f)
            except OSError as e:
                sys.stderr.write('jq: error: Could not open file %s: %s\\n' % (f, e.strerror))
                sys.exit(2)
            datas.append((f, data))
    else:
        data = sys.stdin.buffer.read()
        datas.append((None, data))
    for fname, data in datas:
        st.input_filename = fname if fname is not None else '<stdin>'
        if opts['raw_input']:
            text = data.decode('utf-8', 'surrogateescape')
            lines = text.split('\\n')
            if lines and lines[-1] == '':
                lines.pop()
            nl = 0
            for line in lines:
                nl += 1
                if line.endswith('\\r'):
                    line = line[:-1]
                st.input_line_number = nl
                yield line
            continue
        if opts['seq']:
            for v in seq_values(data, st):
                yield v
            continue
        if opts['stream']:
            for e in stream_values(data, st, opts['stream_errors']):
                yield e
            continue
        for v in json_values_lines(data, st):
            yield v

def json_values_lines(data, st):
    """Parse JSON values feeding the parser line by line so that the input
    line number matches jq's behaviour."""
    pos = 0
    nl = 0
    n = len(data)
    p = JvParser(False)
    while pos < n:
        idx = data.find(b'\\n', pos)
        if idx < 0:
            chunk = data[pos:]
            pos = n
        else:
            chunk = data[pos:idx+1]
            pos = idx + 1
        nl += chunk.count(b'\\n')
        chars, blen = utf8_chars(chunk)
        for i in range(len(chars)):
            ch = chars[i]
            p.col += blen[i]
            if ch == '\\n':
                p.line += 1
                p.col = 0
            p.process(ch)
            if p.out:
                st.input_line_number = nl
                for v in p.out:
                    yield v
                p.out = []
    try:
        p.finish()
    except ParseError as e:
        raise
    if p.out:
        st.input_line_number = nl
        for v in p.out:
            yield v
        p.out = []

'''
