def any: reduce .[] as $x (false; . or $x);
def all: reduce .[] as $x (true; . and $x);
def any(generator; condition): any(generator; condition);
def isempty(f): label $out | (f|false, break $out), true;
def first(f): label $out | (f, break $out);
def last(f): reduce f as $x (null; $x);
def first: .[0];
def last: .[-1];
def nth($n): .[$n];
