def fromdate: fromdateiso8601;
def todateiso8601: strftime("%Y-%m-%dT%H:%M:%SZ");
def fromdateiso8601: strptime("%Y-%m-%dT%H:%M:%SZ")|mktime;
def date: todate;
def dateadd(unit; amount): . + amount;
def datesub(unit; amount): . - amount;
def dateperiods(unit): .;
def match($val): match($val; null);
def test($val): test($val; null);
def capture($val): capture($val; null);
def scan($re): scan($re; null);
def splits($re): splits($re; null);
def split($re): split($re; null);
def sub($re; str): sub($re; str; null);
def gsub($re; str): gsub($re; str; null);
def unique: group_by(.) | map(.[0]);
